  async function inspectRow(cell:SelectedCell){if(!result)return;const job=result.job_id;await perform('读取当前行的来源',async()=>{const data=await api<any>('/api/fill-assist/candidates',json({job_id:job,sheet_name:cell.sheet,row_number:cell.row}));setSources({...data,cell});setView('sources');setVisible(true);add('已为你展开这一行的依据。',[{label:'返回计算表',action:'locate',target:{sheet:cell.sheet,row:cell.row}}],'assistant',false,sourceCard(cell,data.candidates?.length||0));});}
