  async function restore(run:Run,target:'preview'|'report'|'conversation'='preview',loadResult?:()=>Promise<Result>){let succeeded=false;await perform('恢复独立任务成果',async()=>{
    const data=await (loadResult?loadResult():api<Result>(`/api/astra/runs/${run.job_id}`));
    const restoredName=data.project_name||run.name;
    const owner=workspace.jobs[data.job_id];
    if(owner&&workspace.conversations.find(c=>c.id===owner)?.job_id===data.job_id){await workspace.select(owner);acceptResult(data);setView(target==='report'?'report':'table');setVisible(target!=='conversation');setExpanded(false);setSidebar(false);if(target==='report')await refreshReport(data.job_id);succeeded=true;return;}

    if(owner)await workspace.select(owner);else await workspace.create();
    conversationContext.current=crypto.randomUUID();acceptResult(data);setProject(restoredName);setSidebar(false);setFile(null);setInputFileId('');setSheets([]);setRisks([]);setSources(null);setTimeline([]);setView(target==='report'?'report':'table');setVisible(target!=='conversation');setExpanded(false);if(target==='report')await refreshReport(data.job_id);
    const pending=data.summary.matching_status!=='completed';
    add(owner?`已打开本段对话中「${restoredName}」的实际成果，可以继续核对。`:`已恢复「${restoredName}」的实际成果，可从这里接着做。这是恢复提示，原聊天未保存。`,data.needs_recalculate?[{label:'重算公式与报告',action:'recalculate',primary:true}]:pending?[{label:'开始批量匹配',action:'match',primary:true}]:[{label:data.summary.warning_summary?.executed?'查看风险与依据':'检查经验池预警',action:data.summary.warning_summary?.executed?'risk':'warning',primary:true}],'assistant',false,resultCard(data,true));succeeded=true;
  });return succeeded;}
  async function openDashboardRun(projectId:string,runId:string,target:'preview'|'report'|'conversation'){
    if(busyRef.current||!workspace.ready)throw new Error('当前任务仍在处理中，请稍后再打开历史成果。');
    if(!await restore({job_id:'',name:'历史任务',status:'',updated_at:'',rows:0,input_filename:''},target,()=>api<Result>(`/api/projects/${encodeURIComponent(projectId)}/runs/${encodeURIComponent(runId)}/result`)))throw new Error('成果暂未恢复，请检查对话中的错误提示后重试。');
  }
  function newTask(){if(!busyRef.current)void newConversation();}
  function action(name:string){if(name.startsWith('download:')){const url=name.slice(9);if(/^\/api\/(?:settlement-audit|workload-capture)\/(?:download|current-download)\/[a-f0-9]{32}\/[a-z]+$/.test(url))window.open(url,'_blank','noopener');return;}if(name==='attach'){input.current?.click();return;}if(name==='convert'){void convert();return;}if(name==='match'){void match();return;}if(name==='warning'){void warning();return;}if(name==='risk-report'){void generateRisk();return;}if(name==='recalculate'){void recalculate();return;}if(name==='sample'){void sample();return;}if(name==='mapping'&&!file){input.current?.click();return;}open(name);}
  function send(){const text=draft.trim();if(!text||busyRef.current||!workspace.ready)return;setDraft('');add(text,undefined,'user');if(chatMode==='knowledge'||/^#知识|^#知识库/.test(text)){void askKnowledge(text,true);return;}const intents:[RegExp,View][]=[[/Gork|机器人|任务哨兵|任务追踪/i,'gork'],[/工作量|抓取/,'workload'],[/导入.*经验|经验池导入/,'experience'],[/结算|送审/,'settlement'],[/记忆|候选知识/,'memory'],[/展示地图/,'showcase'],[/地图|地点|地理/,'map'],[/能力治理|上岗|Skill/i,'skills'],[/AI.*增强|智能.*编制|字段确认/,'advanced'],[/费用.*图|分析图表/,'analysis'],[/分页|Word 预览/i,'word'],[/配置|设置/,'configuration'],[/派发|回执|通讯录/,'dispatch'],[/双路|对比回答/,'knowledge'],[/数字化项目/,'digital']];const intent=intents.find(([pattern])=>pattern.test(text));if(intent){open(intent[1]);add(`已打开${titles[intent[1]]}。可以在右侧确认输入、执行操作和查看结果。`,[{label:'打开专业详情',action:intent[1],primary:true}],'assistant',false,{kind:'confirmation',title:titles[intent[1]],caption:'专业工具',icon:'grid',status:'等待操作'});return;}if(/架构图|系统架构/.test(text)){open('architecture');return;}if(/智能协同|协同|飞书|WeAct/i.test(text)){open('collaboration');return;}if(/知识网络|文章库/.test(text)){open('articles');return;}if(/知识库|资料库/.test(text)){open('knowledge');return;}if(/^(开始)?批量匹配[。！!\s]*$/.test(text)){void match();return;}if(/^(查看|显示|打开).*(风险|预警|复核)/.test(text)){open('risk');return;}if(/预警|检查风险|复核/.test(text)){if(result)void warning();else add('先添加 Excel，完成转换和匹配后，我会根据实际结果检查风险。',[{label:'添加 Excel',action:'attach',primary:true}]);return;}if(/重算/.test(text)){void recalculate();return;}if(/转换/.test(text)){void convert();return;}if(/报告|导出|下载/.test(text)){if(completed){open('report');add('成果已打开，也可以从下面的卡片切换。',[{label:'补充风险报告',action:'risk-report'}],'assistant',false,artifactCard({...result!,needs_recalculate:needsRecalculate}));}else add('请先完成批量匹配，才能生成正式成果。',[{label:result?'批量匹配':'添加 Excel',action:result?'match':'attach',primary:true}]);return;}if(/表格|计算表/.test(text)){open('table');return;}if(/星图|3d/i.test(text)){open('universe');return;}if(/项目|历史|看板/.test(text)){open('projects');add('项目看板已展开，可以筛选项目、核对进度，或从历史成果继续工作。',[{label:'查看项目看板',action:'projects',primary:true}],'assistant',false,{kind:'confirmation',title:'项目看板',caption:'项目与历史成果',icon:'folder',status:'已打开',note:'统计来自本工作区的真实业务记录。'});return;}add('你可以通过这些已接通的能力，在对话中推进编制。',[{label:result?(completed?'检查经验池预警':'开始批量匹配'):file?'确认结构并转换':'添加 Excel',action:result?(completed?'warning':'match'):file?'convert':'attach',primary:true},{label:'查看全部能力',action:'tools'}],'assistant',false,capabilitiesCard);}

  function unavailable(message:Message,a:Action){return actionUnavailable(message,a,{context:conversationContext.current,result,busy:!!busy,needsRecalculate});}
  function locate(sheet:string,row:number){
    if(!result)return;const previews=result.summary.table_preview.sheets||[result.summary.table_preview];
    const index=previews.findIndex(s=>s.sheet_name===sheet);if(index<0){add('当前预览未包含该工作表，请在完整 Excel 中查看。');return;}
    setSheetIndex(index);setLocatedRow(row);setView('table');setVisible(true);
  }
  function prepareKnowledgeCandidate(message:Message){
    const answer=message.evidence;if(!answer||busyRef.current)return;
    const question=answer.question||messages.slice(0,messages.findIndex(m=>m.id===message.id)).reverse().find(m=>m.role==='user')?.text||'知识问答';
    const references=(answer.sources||[]).map((item:any)=>item.title||item.title_path||item.source_name||item.source||item.source_file||'知识引用').join('；');
    const excerpts=(answer.sources||[]).map((item:any)=>item.snippet||item.excerpt||item.content||item.text||'').filter(Boolean).join('\n\n');
    setKnowledgeSeed({id:crypto.randomUUID(),context:conversationContext.current,title:question.slice(0,120),question,conclusion:['evidence_only','evidence_fallback'].includes(answer.answer_mode)?excerpts:message.text,sourceReference:references,evidenceSummary:excerpts.slice(0,4000),sourceType:'knowledge_answer',jobId:message.job||''});open('memory');
  }
  function messageAction(message:Message,a:Action){if(unavailable(message,a)||busyRef.current)return;if(a.action==='knowledge-result'&&message.evidence){setEvidence(message.evidence);open('knowledge');return;}if(a.action==='locate'&&a.target){locate(a.target.sheet,a.target.row);return;}action(a.action);}

